import java.util.ArrayList;
import java.util.HashMap;

public class WrapperDemo {
    public static void main(String[] args) {

        // Collections require objects — wrappers enable this
        ArrayList<Integer> scores = new ArrayList<>();
        scores.add(95);  // autoboxed: Integer.valueOf(95)
        scores.add(72);
        int first = scores.get(0); // unboxed: .intValue()

        // Utility methods — only available via wrapper class
        int parsed = Integer.parseInt("42");     // String to int
        String bin = Integer.toBinaryString(255); // "11111111"
        System.out.println(bin);

        // Constants
        System.out.println(Integer.MAX_VALUE);   // 2147483647
        System.out.println(Integer.MIN_VALUE);   // -2147483648

        // Character utilities — very useful in string problems
        char c = '5';
        System.out.println(Character.isDigit(c));     // true
        System.out.println(Character.isLetter(c));    // false
        System.out.println(Character.toUpperCase('a')); // A

        // Nullable numeric values — Integer can be null, int cannot
        Integer optionalAge = null;  // represents 'age not provided'
        if (optionalAge != null) {
            System.out.println("Age: " + optionalAge);
        } else {
            System.out.println("Age not provided");
        }
    }
}
