import java.util.ArrayList;

public class ParseVsValueOf {
    public static void main(String[] args) {

        // parseInt — returns primitive int, no object
        int a = Integer.parseInt("42");   // primitive 42
        int b = Integer.parseInt("100");
        System.out.println(a + b); // 142 — direct arithmetic, no boxing

        // valueOf — returns Integer object
        Integer x = Integer.valueOf("42");  // Integer object
        ArrayList<Integer> list = new ArrayList<>();
        list.add(Integer.valueOf("99")); // object added to list
        // or just: list.add(Integer.parseInt("99")); — autoboxing does valueOf() for you

        // Both throw NumberFormatException for invalid input
        try {
            int bad = Integer.parseInt("abc"); // NumberFormatException
        } catch (NumberFormatException e) {
            System.out.println("Not a number: " + e.getMessage());
        }

        // Autoboxing calls valueOf — these are equivalent:
        Integer auto = 5;                    // Integer.valueOf(5)
        Integer manual = Integer.valueOf(5); // same thing
        System.out.println(auto == manual);  // true — both hit the cache
    }
}
