public class MinMaxDemo {
    public static void main(String[] args) {

        // The values
        System.out.println(Integer.MAX_VALUE); // 2147483647
        System.out.println(Integer.MIN_VALUE); // -2147483648

        // Classic use: finding minimum in an array
        int[] arr = {42, 7, 99, 3, 55};
        int min = Integer.MAX_VALUE; // start with largest possible
        for (int x : arr) {
            if (x < min) min = x;    // every real value beats Integer.MAX_VALUE
        }
        System.out.println("Min: " + min); // 3

        // Finding maximum
        int max = Integer.MIN_VALUE;
        for (int x : arr) {
            if (x > max) max = x;
        }
        System.out.println("Max: " + max); // 99

        // OVERFLOW TRAP — silent wrap-around, no exception!
        int big = Integer.MAX_VALUE;
        System.out.println(big + 1); // -2147483648 — wraps to MIN_VALUE!

        // Safe fix: use long
        long safe = (long) Integer.MAX_VALUE + 1;
        System.out.println(safe); // 2147483648 — correct

        // Multiply overflow — common bug
        int a = 100000;
        int b = 100000;
        System.out.println(a * b);            // 1410065408 — WRONG (overflow)
        System.out.println((long) a * b);     // 10000000000 — correct
    }
}
